-- Nordic Supply demo schema (generated by dsgen v2.4.0) — dialect: PostgreSQL
-- Column order matches the CSV files, so loaders can insert without a column list.

CREATE TABLE users (
    id INT PRIMARY KEY,
    username VARCHAR(60) NOT NULL UNIQUE,
    full_name VARCHAR(120) NOT NULL,
    email VARCHAR(160),
    role VARCHAR(30) NOT NULL,
    active BOOLEAN NOT NULL,
    created_at TIMESTAMP NOT NULL
);
COMMENT ON COLUMN users.username IS '[pii:name]';
COMMENT ON COLUMN users.full_name IS '[pii:name]';
COMMENT ON COLUMN users.email IS '[pii:contact]';
COMMENT ON COLUMN users.role IS 'ADMIN, ANALYST, SUPPORT_AGENT, CATALOGUE_MANAGER, ACCOUNT_MANAGER, WAREHOUSE';

CREATE TABLE warehouses (
    id INT PRIMARY KEY,
    code VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(120) NOT NULL,
    country CHAR(2) NOT NULL,
    city VARCHAR(80),
    postal_code VARCHAR(12)
);

CREATE TABLE categories (
    id INT PRIMARY KEY,
    code VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(80) NOT NULL,
    season VARCHAR(10) NOT NULL
);
COMMENT ON COLUMN categories.season IS 'SPRING, SUMMER, AUTUMN, WINTER, ALL';

CREATE TABLE suppliers (
    id INT PRIMARY KEY,
    code VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(120) NOT NULL,
    country CHAR(2) NOT NULL,
    city VARCHAR(80),
    contact_email VARCHAR(160),
    lead_time_days INT NOT NULL,
    active BOOLEAN NOT NULL
);
COMMENT ON COLUMN suppliers.contact_email IS '[pii:contact]';

CREATE TABLE products (
    id INT PRIMARY KEY,
    sku VARCHAR(20) NOT NULL UNIQUE,
    ean CHAR(13) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    description VARCHAR(400),
    category_id INT NOT NULL REFERENCES categories(id),
    supplier_id INT NOT NULL REFERENCES suppliers(id),
    product_type VARCHAR(60) NOT NULL,
    variant VARCHAR(40),
    colour VARCHAR(40),
    unit VARCHAR(10) NOT NULL,
    case_pack INT NOT NULL,
    min_order_qty INT NOT NULL,
    weight_kg DECIMAL(8,3) NOT NULL,
    active BOOLEAN NOT NULL,
    discontinued_on DATE,
    created_at DATE NOT NULL
);
COMMENT ON COLUMN products.sku IS 'e.g. ''FJV-TNT-0010'' (supplier code, category code, sequence)';
COMMENT ON COLUMN products.ean IS 'EAN-13 barcode';
COMMENT ON COLUMN products.name IS 'full display name: brand + model + type + variant + colour';
COMMENT ON COLUMN products.description IS 'short marketing text';
COMMENT ON COLUMN products.category_id IS '-> categories.id';
COMMENT ON COLUMN products.supplier_id IS '-> suppliers.id';
COMMENT ON COLUMN products.product_type IS 'kind of item (''Tent'', ''Hiking Boot'', ''Headlamp'')';
COMMENT ON COLUMN products.variant IS 'size, capacity, temperature rating, length';
COMMENT ON COLUMN products.unit IS '''pcs'' or ''pair''';
COMMENT ON COLUMN products.case_pack IS 'units per carton';
COMMENT ON COLUMN products.weight_kg IS 'per unit';
COMMENT ON COLUMN products.active IS 'FALSE = discontinued';

CREATE TABLE price_history (
    id INT PRIMARY KEY,
    product_id INT NOT NULL REFERENCES products(id),
    list_price DECIMAL(10,2) NOT NULL,
    currency CHAR(3) NOT NULL,
    valid_from DATE NOT NULL,
    valid_to DATE,
    reason VARCHAR(80),
    created_by INT REFERENCES users(id),
    created_at TIMESTAMP NOT NULL
);
COMMENT ON COLUMN price_history.product_id IS '-> products.id';
COMMENT ON COLUMN price_history.currency IS 'always EUR';
COMMENT ON COLUMN price_history.valid_to IS 'NULL on the open-ended row';
COMMENT ON COLUMN price_history.reason IS '''Initial listing'', ''Annual price update'', ''Supplier increase'', ...';
COMMENT ON COLUMN price_history.created_by IS '-> users.id';

CREATE TABLE promotions (
    id INT PRIMARY KEY,
    product_id INT NOT NULL REFERENCES products(id),
    name VARCHAR(80) NOT NULL,
    discount_pct DECIMAL(5,1) NOT NULL,
    promo_price DECIMAL(10,2) NOT NULL,
    starts_on DATE NOT NULL,
    ends_on DATE NOT NULL,
    created_by INT REFERENCES users(id)
);
COMMENT ON COLUMN promotions.product_id IS '-> products.id';
COMMENT ON COLUMN promotions.created_by IS '-> users.id';

CREATE TABLE inventory (
    id INT PRIMARY KEY,
    product_id INT NOT NULL REFERENCES products(id),
    warehouse_id INT NOT NULL REFERENCES warehouses(id),
    on_hand INT NOT NULL,
    reserved INT NOT NULL,
    reorder_point INT NOT NULL,
    next_inbound_date DATE
);
COMMENT ON COLUMN inventory.product_id IS '-> products.id';
COMMENT ON COLUMN inventory.warehouse_id IS '-> warehouses.id';
COMMENT ON COLUMN inventory.reserved IS 'allocated to open orders';
COMMENT ON COLUMN inventory.next_inbound_date IS 'next expected supplier delivery, NULL if none planned';

CREATE TABLE customers (
    id INT PRIMARY KEY,
    customer_number VARCHAR(12) NOT NULL UNIQUE,
    name VARCHAR(160) NOT NULL,
    chain_name VARCHAR(80),
    segment VARCHAR(30) NOT NULL,
    country CHAR(2) NOT NULL,
    city VARCHAR(80) NOT NULL,
    postal_code VARCHAR(12),
    street VARCHAR(120),
    vat_number VARCHAR(20),
    email_domain VARCHAR(80),
    phone VARCHAR(30),
    credit_limit DECIMAL(12,2),
    payment_terms_days INT NOT NULL,
    customer_discount_pct DECIMAL(5,1) NOT NULL,
    account_manager_id INT REFERENCES users(id),
    created_at DATE NOT NULL,
    active BOOLEAN NOT NULL
);
COMMENT ON COLUMN customers.customer_number IS 'business key, e.g. ''C-10001''';
COMMENT ON COLUMN customers.chain_name IS 'groups stores of the same chain (e.g. ''Erävakka''); NULL for independents';
COMMENT ON COLUMN customers.segment IS 'CHAIN_STORE, INDEPENDENT, ONLINE, DEPARTMENT_STORE, RENTAL_OUTFITTER, CLUB_OR_SCHOOL';
COMMENT ON COLUMN customers.country IS 'ISO-2: FI, SE, NO, DK, DE, EE';
COMMENT ON COLUMN customers.phone IS '[pii:contact]';
COMMENT ON COLUMN customers.credit_limit IS 'EUR';
COMMENT ON COLUMN customers.customer_discount_pct IS 'customer-level discount applied to every line';
COMMENT ON COLUMN customers.account_manager_id IS '-> users.id';

CREATE TABLE customer_contacts (
    id INT PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customers(id),
    first_name VARCHAR(60) NOT NULL,
    last_name VARCHAR(60) NOT NULL,
    role VARCHAR(40),
    email VARCHAR(160) NOT NULL UNIQUE,
    phone VARCHAR(30),
    is_primary BOOLEAN NOT NULL,
    language CHAR(2),
    marketing_consent BOOLEAN NOT NULL,
    consent_source VARCHAR(20),
    retention_until DATE
);
COMMENT ON COLUMN customer_contacts.first_name IS '[pii:name]';
COMMENT ON COLUMN customer_contacts.last_name IS '[pii:name]';
COMMENT ON COLUMN customer_contacts.role IS '[pii:identifier]';
COMMENT ON COLUMN customer_contacts.email IS '[pii:contact]';
COMMENT ON COLUMN customer_contacts.phone IS '[pii:contact]';
COMMENT ON COLUMN customer_contacts.language IS '[pii:identifier]';
COMMENT ON COLUMN customer_contacts.marketing_consent IS 'GDPR: may we send marketing [pii:identifier]';
COMMENT ON COLUMN customer_contacts.consent_source IS 'WEBSITE, TRADE_FAIR, ACCOUNT_MANAGER, PORTAL [pii:identifier]';
COMMENT ON COLUMN customer_contacts.retention_until IS 'erase after this date unless there is an open business need [pii:identifier]';

CREATE TABLE delivery_addresses (
    id INT PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customers(id),
    label VARCHAR(60),
    street VARCHAR(120) NOT NULL,
    postal_code VARCHAR(12),
    city VARCHAR(80) NOT NULL,
    country CHAR(2) NOT NULL,
    delivery_instructions VARCHAR(200),
    is_default BOOLEAN NOT NULL
);
COMMENT ON COLUMN delivery_addresses.customer_id IS '-> customers.id';
COMMENT ON COLUMN delivery_addresses.label IS '''Store'', ''Central warehouse'', ''Second store''';
COMMENT ON COLUMN delivery_addresses.delivery_instructions IS '[pii:free-text]';

CREATE TABLE orders (
    id INT PRIMARY KEY,
    order_number VARCHAR(20) NOT NULL UNIQUE,
    customer_id INT NOT NULL REFERENCES customers(id),
    delivery_address_id INT NOT NULL REFERENCES delivery_addresses(id),
    placed_at TIMESTAMP NOT NULL,
    channel VARCHAR(10) NOT NULL,
    status VARCHAR(20) NOT NULL,
    requested_delivery_date DATE,
    promised_ship_date DATE NOT NULL,
    promised_delivery_date DATE NOT NULL,
    currency CHAR(3) NOT NULL,
    total_net DECIMAL(12,2) NOT NULL,
    warehouse_id INT NOT NULL REFERENCES warehouses(id),
    created_by INT REFERENCES users(id),
    customer_reference VARCHAR(40),
    notes VARCHAR(200)
);
COMMENT ON COLUMN orders.order_number IS 'e.g. ''SO-2026-001234''';
COMMENT ON COLUMN orders.customer_id IS '-> customers.id';
COMMENT ON COLUMN orders.delivery_address_id IS '-> delivery_addresses.id';
COMMENT ON COLUMN orders.channel IS 'EDI, PORTAL, EMAIL, PHONE';
COMMENT ON COLUMN orders.status IS 'OPEN, CONFIRMED, PARTIALLY_SHIPPED, SHIPPED, DELIVERED, CANCELLED';
COMMENT ON COLUMN orders.requested_delivery_date IS 'what the customer asked for';
COMMENT ON COLUMN orders.promised_ship_date IS 'the dispatch date we committed to';
COMMENT ON COLUMN orders.promised_delivery_date IS 'the delivery date we committed to';
COMMENT ON COLUMN orders.total_net IS 'order value in EUR after customer discount';
COMMENT ON COLUMN orders.warehouse_id IS '-> warehouses.id, where it ships from';
COMMENT ON COLUMN orders.created_by IS '-> users.id; NULL for EDI/portal orders';
COMMENT ON COLUMN orders.customer_reference IS 'the customer''s own PO number [pii:free-text]';
COMMENT ON COLUMN orders.notes IS '[pii:free-text]';

CREATE TABLE order_lines (
    id INT PRIMARY KEY,
    order_id INT NOT NULL REFERENCES orders(id),
    line_number INT NOT NULL,
    product_id INT NOT NULL REFERENCES products(id),
    quantity INT NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    list_price DECIMAL(10,2) NOT NULL,
    promotion_applied BOOLEAN NOT NULL,
    discount_pct DECIMAL(5,1) NOT NULL,
    line_total DECIMAL(12,2) NOT NULL,
    status VARCHAR(20) NOT NULL,
    backordered_qty INT NOT NULL,
    expected_restock_date DATE
);
COMMENT ON COLUMN order_lines.order_id IS '-> orders.id';
COMMENT ON COLUMN order_lines.product_id IS '-> products.id';
COMMENT ON COLUMN order_lines.quantity IS 'in the product''s unit';
COMMENT ON COLUMN order_lines.unit_price IS 'what was charged (promo price if a promotion applied)';
COMMENT ON COLUMN order_lines.list_price IS 'the price_history price that day';
COMMENT ON COLUMN order_lines.line_total IS 'quantity * unit_price * (1 - discount_pct/100)';
COMMENT ON COLUMN order_lines.status IS 'OPEN (waiting to ship), BACKORDERED (no stock, waiting for supplier), SHIPPED, CANCELLED. A line is currently on backorder only when status = ''BACKORDERED''; backordered_qty/expected_restock_date stay filled on lines that later shipped';

CREATE TABLE shipments (
    id INT PRIMARY KEY,
    shipment_number VARCHAR(20) NOT NULL UNIQUE,
    order_id INT NOT NULL REFERENCES orders(id),
    warehouse_id INT NOT NULL REFERENCES warehouses(id),
    delivery_address_id INT NOT NULL REFERENCES delivery_addresses(id),
    carrier VARCHAR(40) NOT NULL,
    tracking_number VARCHAR(30),
    shipped_at TIMESTAMP NOT NULL,
    expected_delivery_date DATE NOT NULL,
    delivered_at TIMESTAMP,
    status VARCHAR(20) NOT NULL,
    pallet_count INT NOT NULL,
    package_count INT NOT NULL,
    weight_kg DECIMAL(10,1) NOT NULL
);
COMMENT ON COLUMN shipments.shipment_number IS 'e.g. ''SH-2026-001234''';
COMMENT ON COLUMN shipments.order_id IS '-> orders.id';
COMMENT ON COLUMN shipments.warehouse_id IS '-> warehouses.id';
COMMENT ON COLUMN shipments.delivery_address_id IS '-> delivery_addresses.id';
COMMENT ON COLUMN shipments.carrier IS 'Nordfrakt, Polarpost, Kalott Freight, Botnia Cargo, Havnelast, Baltic Freight Line';
COMMENT ON COLUMN shipments.delivered_at IS 'NULL while in transit';
COMMENT ON COLUMN shipments.status IS 'IN_TRANSIT, DELIVERED, EXCEPTION';
COMMENT ON COLUMN shipments.pallet_count IS '0 = parcel shipment';

CREATE TABLE shipment_lines (
    id INT PRIMARY KEY,
    shipment_id INT NOT NULL REFERENCES shipments(id),
    order_line_id INT NOT NULL REFERENCES order_lines(id),
    quantity INT NOT NULL,
    pallet_number INT
);
COMMENT ON COLUMN shipment_lines.shipment_id IS '-> shipments.id';
COMMENT ON COLUMN shipment_lines.order_line_id IS '-> order_lines.id';
COMMENT ON COLUMN shipment_lines.pallet_number IS '1 = first pallet; NULL for parcel shipments';

CREATE TABLE delivery_events (
    id INT PRIMARY KEY,
    shipment_id INT NOT NULL REFERENCES shipments(id),
    event_time TIMESTAMP NOT NULL,
    event_type VARCHAR(30) NOT NULL,
    location VARCHAR(80),
    note VARCHAR(200)
);
COMMENT ON COLUMN delivery_events.shipment_id IS '-> shipments.id';
COMMENT ON COLUMN delivery_events.event_type IS 'PICKED, PACKED, DISPATCHED, HUB_SCAN, DELAYED, OUT_FOR_DELIVERY, DELIVERY_ATTEMPTED, DELIVERED, EXCEPTION, DAMAGE_REPORTED';
COMMENT ON COLUMN delivery_events.note IS 'reason for DELAYED/EXCEPTION, who signed for DELIVERED [pii:free-text]';

CREATE TABLE claims (
    id INT PRIMARY KEY,
    claim_number VARCHAR(20) NOT NULL UNIQUE,
    customer_id INT NOT NULL REFERENCES customers(id),
    order_id INT REFERENCES orders(id),
    shipment_id INT REFERENCES shipments(id),
    claim_type VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    priority VARCHAR(10) NOT NULL,
    source VARCHAR(10) NOT NULL,
    reported_by_contact_id INT REFERENCES customer_contacts(id),
    assigned_to INT REFERENCES users(id),
    opened_at TIMESTAMP NOT NULL,
    resolved_at TIMESTAMP,
    needed_by DATE,
    requested_resolution VARCHAR(30),
    claimed_amount DECIMAL(12,2),
    approved_amount DECIMAL(12,2),
    description VARCHAR(1000),
    resolution_note VARCHAR(400)
);
COMMENT ON COLUMN claims.claim_number IS 'e.g. ''CL-2026-00123''';
COMMENT ON COLUMN claims.customer_id IS '-> customers.id';
COMMENT ON COLUMN claims.order_id IS '-> orders.id';
COMMENT ON COLUMN claims.shipment_id IS '-> shipments.id';
COMMENT ON COLUMN claims.claim_type IS 'DAMAGED, MISSING_ITEMS, WRONG_ITEM, LATE_DELIVERY, QUALITY_DEFECT, PRICING_DISPUTE, RETURN_REQUEST';
COMMENT ON COLUMN claims.status IS 'NEW, UNDER_REVIEW, AWAITING_CUSTOMER, APPROVED, REJECTED, RESOLVED, CLOSED';
COMMENT ON COLUMN claims.priority IS 'LOW, NORMAL, HIGH, URGENT';
COMMENT ON COLUMN claims.source IS 'EMAIL, PORTAL, PHONE';
COMMENT ON COLUMN claims.reported_by_contact_id IS '[pii:identifier]';
COMMENT ON COLUMN claims.assigned_to IS '-> users.id; NULL = unassigned';
COMMENT ON COLUMN claims.needed_by IS 'date the customer needs a resolution by';
COMMENT ON COLUMN claims.requested_resolution IS 'REPLACEMENT, REDELIVERY, CREDIT, REPAIR, RETURN_AUTHORISATION';
COMMENT ON COLUMN claims.claimed_amount IS 'EUR';
COMMENT ON COLUMN claims.approved_amount IS 'EUR, NULL until decided';
COMMENT ON COLUMN claims.description IS 'the agent''s summary [pii:free-text]';
COMMENT ON COLUMN claims.resolution_note IS '[pii:free-text]';

CREATE TABLE claim_lines (
    id INT PRIMARY KEY,
    claim_id INT NOT NULL REFERENCES claims(id),
    order_line_id INT REFERENCES order_lines(id),
    product_id INT REFERENCES products(id),
    quantity_affected INT NOT NULL,
    pallet_number INT,
    amount DECIMAL(12,2),
    issue_note VARCHAR(200)
);
COMMENT ON COLUMN claim_lines.claim_id IS '-> claims.id';
COMMENT ON COLUMN claim_lines.order_line_id IS '-> order_lines.id';
COMMENT ON COLUMN claim_lines.product_id IS '-> products.id';
COMMENT ON COLUMN claim_lines.amount IS 'EUR';
COMMENT ON COLUMN claim_lines.issue_note IS '[pii:free-text]';

CREATE TABLE saved_widgets (
    id INT PRIMARY KEY,
    user_id INT NOT NULL REFERENCES users(id),
    title VARCHAR(160) NOT NULL,
    description VARCHAR(1000),
    widget_type VARCHAR(10) NOT NULL,
    query_sql TEXT,
    state_json TEXT,
    position INT NOT NULL,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL
);
COMMENT ON COLUMN saved_widgets.description IS '[pii:free-text]';

-- Activity log: written by the application from the AI request/response listeners and the
-- controllers' state-change listeners. Never seeded; one row per AI turn.
CREATE TABLE activity_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    occurred_at TIMESTAMP NOT NULL,
    user_id INT REFERENCES users(id),
    view_name VARCHAR(40) NOT NULL,            -- INSIGHTS, CLAIM_FORM, CATALOGUE
    widget_id INT REFERENCES saved_widgets(id),
    prompt TEXT,                               -- what the user typed
    prompt_sent TEXT,                          -- what actually went to the provider (after masking)
    data_scope VARCHAR(400),                   -- what the model was allowed to see (schema, form fields, ...)
    proposal TEXT,                             -- what the model proposed (query, field values, row changes)
    decision VARCHAR(20),                      -- APPLIED, REJECTED, PARTIAL, UNDONE
    rejection_rule VARCHAR(200),               -- which validation rule or policy rejected it
    model_name VARCHAR(80),
    finish_reason VARCHAR(40),
    input_tokens INT,
    output_tokens INT
);
CREATE INDEX ix_activity_log_user ON activity_log(user_id, occurred_at);

-- Case 3: proposed bulk changes and their outcome. Never seeded.
CREATE TABLE bulk_change_batches (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP NOT NULL,
    created_by INT NOT NULL REFERENCES users(id),
    prompt TEXT NOT NULL,
    description VARCHAR(400),                  -- the model's plain-English reading of the rule
    status VARCHAR(20) NOT NULL,               -- PROPOSED, APPLIED, UNDONE, DISCARDED
    applied_at TIMESTAMP,
    undone_at TIMESTAMP
);
CREATE TABLE bulk_change_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id BIGINT NOT NULL REFERENCES bulk_change_batches(id),
    product_id INT NOT NULL REFERENCES products(id),
    field_name VARCHAR(40) NOT NULL,           -- e.g. list_price
    old_value VARCHAR(80),
    new_value VARCHAR(80),
    effective_from DATE,
    accepted BOOLEAN NOT NULL,                 -- kept in the review list or removed by the user
    price_history_id INT REFERENCES price_history(id)
);

CREATE INDEX ix_products_category ON products(category_id);
CREATE INDEX ix_products_supplier ON products(supplier_id);
CREATE INDEX ix_price_history_product ON price_history(product_id, valid_from);
CREATE INDEX ix_promotions_product ON promotions(product_id, starts_on, ends_on);
CREATE INDEX ix_customers_name ON customers(name);
CREATE INDEX ix_contacts_customer ON customer_contacts(customer_id);
CREATE INDEX ix_contacts_email ON customer_contacts(email);
CREATE INDEX ix_addresses_customer ON delivery_addresses(customer_id);
CREATE INDEX ix_orders_customer ON orders(customer_id, placed_at);
CREATE INDEX ix_orders_placed ON orders(placed_at);
CREATE INDEX ix_orders_status ON orders(status);
CREATE INDEX ix_order_lines_order ON order_lines(order_id);
CREATE INDEX ix_order_lines_product ON order_lines(product_id);
CREATE INDEX ix_order_lines_status ON order_lines(status);
CREATE INDEX ix_shipments_order ON shipments(order_id);
CREATE INDEX ix_shipments_shipped ON shipments(shipped_at);
CREATE INDEX ix_shipment_lines_shipment ON shipment_lines(shipment_id);
CREATE INDEX ix_delivery_events_shipment ON delivery_events(shipment_id, event_time);
CREATE INDEX ix_claims_customer ON claims(customer_id);
CREATE INDEX ix_claims_status ON claims(status, opened_at);
CREATE INDEX ix_claim_lines_claim ON claim_lines(claim_id);

-- Convenience views for the AI schema. They avoid the most error-prone joins.
CREATE VIEW product_current_prices AS
SELECT p.id AS product_id, p.sku, p.name, p.category_id, p.supplier_id, ph.list_price, ph.valid_from
FROM products p JOIN price_history ph ON ph.product_id = p.id
WHERE ph.valid_from <= CURRENT_DATE AND (ph.valid_to IS NULL OR ph.valid_to >= CURRENT_DATE);

CREATE VIEW late_shipments AS
SELECT s.id AS shipment_id, s.shipment_number, o.id AS order_id, o.order_number, o.customer_id,
       s.warehouse_id, s.carrier, o.promised_ship_date, CAST(s.shipped_at AS DATE) AS shipped_on,
       o.promised_delivery_date, CAST(s.delivered_at AS DATE) AS delivered_on
FROM shipments s JOIN orders o ON o.id = s.order_id
WHERE CAST(s.shipped_at AS DATE) > o.promised_ship_date
   OR (s.delivered_at IS NOT NULL AND CAST(s.delivered_at AS DATE) > o.promised_delivery_date);

CREATE VIEW open_claims AS
SELECT c.*, cu.name AS customer_name, cu.country AS customer_country
FROM claims c JOIN customers cu ON cu.id = c.customer_id
WHERE c.status NOT IN ('RESOLVED', 'CLOSED', 'REJECTED');
